t='......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......'
n=len(t)
pairs={}
stack=[]
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j
# Compute nesting depth for each position
depth=0
dep=[0]*n
for i,c in enumerate(t):
    if c=='(':
        depth+=1
        dep[i]=depth
    elif c==')':
        dep[i]=depth
        depth-=1
    else:
        dep[i]=depth
seq=['U']*n
openlist=sorted([i for i in range(n) if t[i]=='('])
helices=[]
i=0
while i < len(openlist):
    run=[openlist[i]]
    while i+1 < len(openlist) and openlist[i+1]==openlist[i]+1:
        run.append(openlist[i+1]); i+=1
    helices.append(run); i+=1
# Assign by depth parity: even depth -> GC, odd depth -> CG
for run in helices:
    d=dep[run[0]]
    for idx,o in enumerate(run):
        c=pairs[o]
        if d % 2 == 0:
            seq[o]='G'; seq[c]='C'
        else:
            seq[o]='C'; seq[c]='G'
seq=''.join(seq)
print(seq)
print('len',len(seq))
# print depths of each helix
for run in helices:
    print('helix open',run,'depth',dep[run[0]],'close',[pairs[x] for x in run])
